using System.IO;
using Microsoft.Win32;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
namespace MRS;
internal sealed class FoxMap : UserControl,IDisposable
{
 private readonly Canvas canvas=new(){Background=new SolidColorBrush(Color.FromRgb(10,20,32)),ClipToBounds=true};private readonly CheckBox follow=new(){Content="Follow position",IsChecked=true,Foreground=Brushes.Gainsboro};private readonly TextBlock info=new(){Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap};private IReadOnlyList<FoxPoint> points=[];private FoxFix? fix;private double cx=.5,cy=.5;private int zoom=3;private Point? drag;private bool positioned;private readonly OfflineDetailSelection mapDetail=new();private FoxEstimate? estimate;
 internal FoxMap(){mapDetail.Changed+=()=>{if(Dispatcher.CheckAccess())Draw();else Dispatcher.BeginInvoke(Draw);};var root=new DockPanel();var header=new StackPanel();DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);var row=new WrapPanel();header.Children.Add(row);void Button(string label,Action action){var b=new Button{Content=label,Padding=new(8,3,8,3)};row.Children.Add(b);b.Click+=(_,_)=>action();}Button("−",()=>Zoom(-1));Button("+",()=>Zoom(1));Button("Fit route",Fit);row.Children.Add(follow);Button("Load offline detail…",()=>_=ChooseDetail());Button("Remove detail",()=>mapDetail.Remove());Button("Map sources",()=>MessageBox.Show("Embedded basemap: Natural Earth (public domain). Optional local WGS84 GeoJSON roads/boundaries/places. No map network requests.\n\n"+mapDetail.Description,"Fox Hunt map"));header.Children.Add(info);root.Children.Add(canvas);Content=root;canvas.SizeChanged+=(_,_)=>Draw();follow.Checked+=(_,_)=>Draw();canvas.MouseWheel+=(_,e)=>{Zoom(e.Delta>0?1:-1);e.Handled=true;};canvas.MouseLeftButtonDown+=(_,e)=>{drag=e.GetPosition(canvas);follow.IsChecked=false;canvas.CaptureMouse();};canvas.MouseMove+=(_,e)=>{if(drag is {} start){var p=e.GetPosition(canvas);double size=256*Math.Pow(2,zoom);cx=AircraftMap.Wrap(cx-(p.X-start.X)/size);cy=Math.Clamp(cy-(p.Y-start.Y)/size,0,1);drag=p;Draw();}};canvas.MouseLeftButtonUp+=(_,_)=>{drag=null;canvas.ReleaseMouseCapture();};canvas.LostMouseCapture+=(_,_)=>drag=null;}
 internal void SetEstimate(FoxEstimate? result){if(estimate==result)return;estimate=result;Draw();}
 private async Task ChooseDetail(){var picker=new OpenFileDialog{Filter="Offline GeoJSON|*.geojson;*.json",Title="Load local WGS84 road / place / boundary detail"};if(picker.ShowDialog(Window.GetWindow(this))!=true)return;try{await LoadDetail(picker.FileName);}catch(Exception ex){MessageBox.Show(ex.Message,"Offline detail import");}}
 internal Task LoadDetail(string path)=>mapDetail.Load(path);
 internal Task ConfigureDetail(string settingsPath)=>mapDetail.Configure(settingsPath);
 public void Dispose()=>mapDetail.Dispose();
 internal void Update(IReadOnlyList<FoxPoint> values,FoxFix? position){points=values;fix=position;if(!positioned&&position!=null){var p=AircraftMap.Project(position.Latitude,position.Longitude);cx=p.X;cy=p.Y;zoom=12;positioned=true;}Draw();}
 private void Zoom(int delta){zoom=Math.Clamp(zoom+delta,2,18);Draw();}
 internal void Fit()
 {
  if(points.Count==0)return;
  var values=points.Select(p=>AircraftMap.Project(p.Fix.Latitude,p.Fix.Longitude)).ToArray();double origin=values[0].X;
  var xs=values.Select(p=>origin+AircraftMap.Wrap(p.X-origin+.5)-.5).ToArray();
  cx=AircraftMap.Wrap((xs.Min()+xs.Max())/2);cy=(values.Min(p=>p.Y)+values.Max(p=>p.Y))/2;
  double scaleX=Math.Max(100,canvas.ActualWidth-70)/(256*Math.Max(.00002,xs.Max()-xs.Min()));
  double scaleY=Math.Max(100,canvas.ActualHeight-70)/(256*Math.Max(.00002,values.Max(p=>p.Y)-values.Min(p=>p.Y)));
  zoom=Math.Clamp((int)Math.Floor(Math.Log2(Math.Min(scaleX,scaleY))),2,17);follow.IsChecked=false;Draw();
 }
 internal static Color SignalColor(double db,double low,double high){double t=Math.Clamp((db-low)/Math.Max(1,high-low),0,1);return Color.FromRgb((byte)(255*t),(byte)(190*(1-Math.Abs(2*t-1))),(byte)(255*(1-t)));}
 private void Draw(){if(canvas.ActualWidth<1||canvas.ActualHeight<1)return;var detail=mapDetail.Current;if(follow.IsChecked==true&&fix is {} f){var p=AircraftMap.Project(f.Latitude,f.Longitude);cx=p.X;cy=p.Y;}canvas.Children.Clear();OfflineBasemap.Shared.Value.Draw(canvas,cx,cy,zoom);detail?.Draw(canvas,cx,cy,zoom);var visible=points.Skip(Math.Max(0,points.Count-5000)).ToArray();double low=points.Count>0?points.Min(p=>p.MeanDb):-100,high=points.Count>0?points.Max(p=>p.MeanDb):-30;if(high-low<10){double middle=(high+low)/2;low=middle-5;high=middle+5;}canvas.Children.Add(new Plot(visible,fix,cx,cy,zoom,low,high){Width=canvas.ActualWidth,Height=canvas.ActualHeight,IsHitTestVisible=false});if(estimate?.Latitude!=null)canvas.Children.Add(new EstimatePlot(estimate,cx,cy,zoom){Width=canvas.ActualWidth,Height=canvas.ActualHeight,IsHitTestVisible=false});var north=new TextBlock{Text="N ↑",Foreground=Brushes.White,Background=Brushes.Black,Padding=new(3),IsHitTestVisible=false};Canvas.SetRight(north,8);Canvas.SetTop(north,8);canvas.Children.Add(north);double latitude=Math.Atan(Math.Sinh(Math.PI*(1-2*cy)))*180/Math.PI;double metresPerPixel=40075016.686*Math.Cos(latitude*Math.PI/180)/(256*Math.Pow(2,zoom));double goal=metresPerPixel*100;double magnitude=Math.Pow(10,Math.Floor(Math.Log10(Math.Max(.001,goal))));double distance=(goal/magnitude>=5?5:goal/magnitude>=2?2:1)*magnitude;var scaleLabel=new TextBlock{Text=distance>=1000?$"≈ {distance/1000:0.#} km":$"≈ {distance:0.#} m",Foreground=Brushes.White,Background=Brushes.Black,IsHitTestVisible=false};Canvas.SetLeft(scaleLabel,10);Canvas.SetBottom(scaleLabel,10);canvas.Children.Add(scaleLabel);var bar=new System.Windows.Shapes.Line{X1=10,X2=10+distance/metresPerPixel,Y1=canvas.ActualHeight-8,Y2=canvas.ActualHeight-8,Stroke=Brushes.White,StrokeThickness=2,IsHitTestVisible=false};canvas.Children.Add(bar);info.Text=(detail!=null?$"Offline detail: {detail.Name} · {(detail.Covers(cx,cy)?"features near view center":"outside detailed coverage at view center")} · ":"Offline Natural Earth · ")+$"zoom {zoom} · wheel zoom / drag pan · blue weaker {low:F1}, red stronger {high:F1} dB relative · {visible.Length}/{points.Count} points drawn"+(mapDetail.Status.Length>0?" · "+mapDetail.Status:"")+(OfflineBasemap.Shared.Value.Error.Length>0?" · "+OfflineBasemap.Shared.Value.Error:"");}
 private sealed class EstimatePlot(FoxEstimate result,double cx,double cy,int zoom):FrameworkElement
 {
  protected override void OnRender(DrawingContext dc){if(result.Latitude is not double lat||result.Longitude is not double lon)return;double size=256*Math.Pow(2,zoom);var p=AircraftMap.Project(lat,lon);var center=new Point(ActualWidth/2+(AircraftMap.Wrap(p.X-cx+.5)-.5)*size,ActualHeight/2+(p.Y-cy)*size);double metresPerPixel=40075016.686*Math.Cos(lat*Math.PI/180)/size,radius=result.RadiusMetres/metresPerPixel;dc.PushClip(new RectangleGeometry(new Rect(0,0,ActualWidth,ActualHeight)));dc.DrawEllipse(new SolidColorBrush(Color.FromArgb(28,255,205,60)),new Pen(Brushes.Gold,2){DashStyle=DashStyles.Dash},center,radius,radius);dc.DrawRectangle(Brushes.Gold,new Pen(Brushes.Black,1),new Rect(center.X-5,center.Y-5,10,10));var text=new FormattedText("Rough source area",System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),12,Brushes.Gold,1);dc.DrawText(text,new(center.X+9,center.Y-18));dc.Pop();}
 }
 private sealed class Plot(FoxPoint[] points,FoxFix? fix,double cx,double cy,int zoom,double low,double high):FrameworkElement
 {
  protected override void OnRender(DrawingContext d){d.PushClip(new RectangleGeometry(new Rect(0,0,ActualWidth,ActualHeight)));double scale=256*Math.Pow(2,zoom);Point Screen(double lat,double lon){var p=AircraftMap.Project(lat,lon);return new(ActualWidth/2+(AircraftMap.Wrap(p.X-cx+.5)-.5)*scale,ActualHeight/2+(p.Y-cy)*scale);}Point? previous=null;FoxPoint? last=null;var line=new Pen(Brushes.SlateGray,1);foreach(var p in points){var pos=Screen(p.Fix.Latitude,p.Fix.Longitude);if(last!=null&&previous is {} start&&p.Segment==last.Segment&&Math.Abs(p.Fix.Longitude-last.Fix.Longitude)<180)d.DrawLine(line,start,pos);if(pos.X>=-6&&pos.Y>=-6&&pos.X<=ActualWidth+6&&pos.Y<=ActualHeight+6)d.DrawEllipse(new SolidColorBrush(SignalColor(p.MeanDb,low,high)),new Pen(Brushes.Black,.5),pos,4,4);previous=pos;last=p;}if(fix!=null){var pos=Screen(fix.Latitude,fix.Longitude);d.DrawEllipse(null,new Pen(Brushes.White,2),pos,8,8);d.DrawLine(new Pen(Brushes.White,1),new(pos.X-12,pos.Y),new(pos.X+12,pos.Y));d.DrawLine(new Pen(Brushes.White,1),new(pos.X,pos.Y-12),new(pos.X,pos.Y+12));}d.Pop();}
 }
}
